import { useSync } from "../../../contexts/sync-context";
import { useToastContext } from "../../../contexts/ToastContext";
import { useAiProvidersLive } from "../../../hooks/use-ai-providers-live";
import { useTranslate } from "../../../i18n/use-translate";
import { Button } from "../../atoms/Button";
import { EncryptionSection } from "./EncryptionSection";
import { SyncStatusLine } from "./SyncStatusLine";

export const SyncTab: React.FC = () => {
  const t = useTranslate("settings");
  const sync = useSync();
  const toast = useToastContext();
  const providers = useAiProvidersLive();
  const hasAiKeys = (providers?.length ?? 0) > 0;

  const handleConnect = async () => {
    try {
      await sync.connect();
    } catch {
      toast.error(t("sync.connectFailed"));
    }
  };

  const handleSyncNow = async () => {
    const outcome = await sync.syncNow();
    if (outcome === "synced") toast.success(t("sync.synced"));
    else if (outcome === "failed" || outcome === "needsAuth")
      toast.error(t("sync.syncFailed"));
  };

  return (
    <div className="space-y-4" data-testid="sync-tab">
      <p className="text-sm text-ink-body">{t("sync.description")}</p>
      <SyncStatusLine
        connected={sync.connected}
        status={sync.status}
        lastSyncedAt={sync.lastSyncedAt}
      />
      <div className="flex flex-wrap gap-2">
        {sync.connected ? (
          <>
            <Button
              size="sm"
              variant="secondary"
              loading={sync.status === "syncing"}
              onClick={handleSyncNow}
            >
              {t("sync.syncNow")}
            </Button>
            <Button
              size="sm"
              variant="tertiary"
              onClick={sync.disconnect}
              data-no-sync-resume=""
            >
              {t("sync.disconnect")}
            </Button>
          </>
        ) : (
          <Button size="sm" variant="primary" onClick={handleConnect}>
            {t("sync.connect")}
          </Button>
        )}
      </div>
      <EncryptionSection hasAiKeys={hasAiKeys} />
    </div>
  );
};
